function maximumXOR(nums) {
  // Every value an operation can produce from v is a submask of v; try all choices.
  let reachable = new Set([0]);
  for (const v of nums) {
    const next = new Set();
    for (const total of reachable) {
      // Walk through every submask of v, from v itself down to 0.
      for (let sub = v; ; sub = (sub - 1) & v) {
        next.add(total ^ sub);
        if (sub === 0) break;
      }
    }
    reachable = next;
  }
  return Math.max(...reachable);
}

